      if (frac < 0.25) {
         bins[0] += 1;
      } else if (frac < 0.5) {
         bins[1] += 1;
      } else if (frac < 0.75) {
         bins[2] += 1;
      } else {
         bins[3] += 1;
      }
   }
}

