#include <algorithm>

struct COOElement {
   size_t row, column;
   double value;
};

struct CSRFormat {
   std::vector<double> values;
   std::vector<size_t> columnIndices;
   std::vector<size_t> rowPointers;
};

CSRFormat convertToCSR(std::vector<COOElement> const& A, size_t N) {
   CSRFormat csr;
   csr.values.reserve(A.size());
   csr.columnIndices.reserve(A.size());
   csr.rowPointers.resize(N + 1);

   for (const auto& element : A) {
      csr.values.push_back(element.value);
      csr.columnIndices.push_back(element.column);
      csr.rowPointers[element.row + 1]++;
   }

   for (size_t i = 1; i <= N; ++i) {
      csr.rowPointers[i] += csr.rowPointers[i - 1];
   }

   return csr;
}

void solveLinearSystem(CSRFormat const& csr, std::vector<double> const& b, std::vector<double> &x, size_t N) {
   x.assign(N, 0.0);
   std::vector<double> b_copy = b;

   // Perform Gaussian elimination
   for (size_t i = 0; i < N; ++i) {
      // Find pivot
      double maxEl = std::abs(csr.values[csr.rowPointers[i]]);
      size_t maxRow = i;
      for (size_t k = i + 1; k < N; ++k) {
         if (std::abs(csr.values[csr.rowPointers[k]]) > maxEl) {
               maxEl = std::abs(csr.values[csr.rowPointers[k]]);
               maxRow = k;
         }
      }

      // Swap maximum row with current row (column by column)
      std::swap(csr.values[csr.rowPointers[maxRow]], csr.values[csr.rowPointers[i]]);
      std::swap(b_copy[maxRow], b_copy[i]);

      // Make all rows below this one 0 in the current column
      for (size_t k = i + 1; k < N; ++k) {
         double c = -csr.values[csr.rowPointers[k]] / csr.values[csr.rowPointers[i]];
         csr.values[csr.rowPointers[k]] += c * csr.values[csr.rowPointers[i]];
         b_copy[k] += c * b_copy[i];
      }
