// Compute the fourier transform of x. Store real part of results in r and imaginary in i.
void fft(std::vector<std::complex<double>>& x, std::vector<double>& r, std::vector<double>& i) {
    unsigned int N = x.size();
    unsigned int m = log2(N);

    // Bit reversal permutation
    for (unsigned int i = 0; i < N; i++) {
        unsigned int j = bitReverse(i, m);
        if (i < j) {
            std::swap(x[i], x[j]);
        }
    }

    // Cooley-Tukey FFT
    for (unsigned int s = 1; s <= m; s++) {
        unsigned int m = (1 << s);
        double theta = -2.0 * M_PI / m;
        std::complex<double> wm = std::exp(theta * std::complex<double>(0, 1));
        for (unsigned int k = 0; k < N; k += m) {
            std::complex<double> w = 1;
            for (unsigned int j = 0; j < m/2; j++) {
                std::complex<double> t = w * x[k + j + m/2];
                std::complex<double> u = x[k + j];
                x[k + j] = u + t;
                x[k + j + m/2] = u - t;
                w *= wm;
            }
        }
    }

    // split into real and imaginary parts
    for (size_t j = 0; j < x.size(); j += 1) {
        r[j] = x[j].real();
        i[j] = x[j].imag();
    }
}

// Bit reversal permutation
unsigned int bitReverse(unsigned int x, unsigned int bits) {
    unsigned int y = 0;
    for (unsigned int i = 0; i < bits; i++) {
        y = (y << 1) | (x & 1);
        x >>= 1;
    }
    return y;
}

