};

double distance(Point const& p1, Point const& p2) {
    return std::sqrt(std::pow(p2.x-p1.x, 2) + std::pow(p2.y-p1.y, 2));
}

bool compareX(Point const& p1, Point const& p2) {
    return p1.x < p2.x;
}

bool compareY(Point const& p1, Point const& p2) {
    return p1.y < p2.y;
}

double stripClosest(std::vector<Point> strip, double d) {
    double min = d;
    std::sort(strip.begin(), strip.end(), compareY);
    for (size_t i = 0; i < strip.size(); ++i) {
        for (size_t j = i+1; j < strip.size() && (strip[j].y - strip[i].y) < min; ++j) {
            double dist = distance(strip[i],strip[j]);
            if (dist < min) {
                min = dist;
            }
        }
    }
    return min;
}

double closestUtil(std::vector<Point> P, int n) {
    if (n <= 3) {
        return closestPair(P);
    }
    int mid = n/2;
    Point midPoint = P[mid];
    double dl = closestUtil(P, mid);
    double dr = closestUtil(P + mid, n-mid);
    double d = std::min(dl, dr);
    std::vector<Point> strip;
    for (int i = 0; i < n; i++) {
        if (std::abs(P[i].x - midPoint.x) < d) {
            strip.push_back(P[i]);
        }
    }
    return std::min(d, stripClosest(strip, d));
}

double closest(std::vector<Point> P) {
    std::sort(P.begin(), P.end(), compareX);
    return closestUtil(P, P.size());
}
