struct Point {
   double x, y;
};

/* Find the set of points that defined the smallest convex polygon that contains all the points in the vector points. Store the result in `hull`.
   Example:

   input: [{0, 3}, {1, 1}, {2, 2}, {4, 4}, {0, 0}, {1, 2}, {3, 1}, {3, 3}]
   output: [{0, 3}, {4, 4}, {3, 1}, {0, 0}]
*/
void convexHull(std::vector<Point> &points, std::vector<Point> &hull) {
    // The polygon needs to have at least three points
    if (points.size() < 3)   {
        hull = points;
        return;
    }

    // Sort the points by x-coordinate, then by y-coordinate
    std::sort(points.begin(), points.end(), [](Point const& a, Point const& b) {
        return a.x < b.x || (a.x == b.x && a.y < b.y);
    });

    // Define a lambda function to calculate the cross product of vectors AB and BC
    auto CrossProduct = [](Point const& a, Point const& b, Point const& c) {
        return (c.x - a.x) * (b.y - a.y) - (c.y - a.y) * (b.x - a.x) > 0;
    };

    // Find the upper hull
    std::vector<Point> upperHull;
    upperHull.push_back(points[0]);
    upperHull.push_back(points[1]);
    for (size_t i = 2; i < points.size(); i++) {
        while (upperHull.size() > 1
               &&!CrossProduct(upperHull[upperHull.size() - 2],
                                upperHull[upperHull.size() - 1],
                                points[i])) {
            upperHull.pop_back();
        }
        upperHull.push_back(points[i]);
    }

    // Find the lower hull
    std::vector<Point> lowerHull;
    lowerHull.push_back(points[points.size() - 1]);
    lowerHull.push_back(points[points.size() - 2]);
    for (size_t i = points.size() - 3; i > 0; i--) {
        while (lowerHull.size() > 1
               &&!CrossProduct(lowerHull[lowerHull.size() - 2],
                                lowerHull[lowerHull.size() - 1],
                                points[i])) {
            lowerHull.pop_back();
        }
        lowerHull.push_back(points[i]);
    }

    // Combine the upper and lower hulls
    hull = upperHull;
    hull.insert(hull.end(), lowerHull.begin() + 1, lowerHull.end() - 1);
    return;
}

