            for (int dx = -1; dx <= 1; dx++) {
                for (int dy = -1; dy <= 1; dy++) {
                    if (dx == 0 && dy == 0) continue;
                    int x = i + dx, y = j + dy;
                    if (x >= 0 && x < N && y >= 0 && y < N) {
                        sum += input[x * N + y];
                    }
                }
            }
            if (input[i * N + j] == 1) {
                output[i * N + j] = (sum == 2 || sum == 3)? 1 : 0;
            } else {
                output[i * N + j] = (sum == 3)? 1 : 0;
            }
        }
    }
}

