/*
 * This function finds the index of the value in the vector x that is closest to the math constant PI.
 * It uses the absolute difference between each value in the vector and PI to determine the closest value.
 *
 * @param x: A vector of doubles.
 * @return: The index of the value in the vector that is closest to PI.
 */
size_t findClosestToPi(std::vector<double> const& x) {
    // Initialize the index and minimum difference with the first element of the vector
    size_t closestIndex = 0;
    double minDifference = std::abs(x[0] - M_PI);

    // Iterate through the vector starting from the second element
    for (size_t i = 1; i < x.size(); ++i) {
        // Calculate the absolute difference between the current element and PI
        double currentDifference = std::abs(x[i] - M_PI);

        // If the current difference is smaller than the minimum difference, update the minimum difference and the index
        if (currentDifference < minDifference) {
            minDifference = currentDifference;
            closestIndex = i;
        }
    }

    // Return the index of the value closest to PI
    return closestIndex;
}

